import * as THREE from './vendor/three.module.js';
import {VOLT_STORM as C} from './runner-storm.js?v=volt-storm-259';
export class RunnerStormFX {
 constructor(scene,camera){this.camera=camera;this.root=new THREE.Group();scene.add(this.root);const mat=(color,opacity=1)=>new THREE.MeshBasicMaterial({color,transparent:opacity<1,opacity,depthWrite:false,toneMapped:false,side:THREE.DoubleSide});this.core=new THREE.Mesh(new THREE.IcosahedronGeometry(1,2),mat('#d5ffff',.8));this.halo=new THREE.Mesh(this.core.geometry,mat('#368dff',.15));this.shell=new THREE.Mesh(new THREE.IcosahedronGeometry(1,1),new THREE.MeshBasicMaterial({color:'#83caff',wireframe:true,transparent:true,opacity:.5,toneMapped:false}));this.marker=new THREE.Mesh(new THREE.RingGeometry(.9,1,64),mat('#7fedff',.8));this.marker.rotation.x=-Math.PI/2;this.shock=new THREE.Mesh(new THREE.SphereGeometry(1,24,12),mat('#adfaff',.2));this.lines=new THREE.InstancedMesh(new THREE.CylinderGeometry(1,1,1,5,1,true),mat('#c9ffff'),256);this.lines.frustumCulled=false;this.bar=new THREE.Group();this.back=new THREE.Mesh(new THREE.PlaneGeometry(2.9,.27),mat('#061322'));this.fill=new THREE.Mesh(new THREE.PlaneGeometry(2.6,.15),mat('#67edff'));this.fill.position.z=.012;this.bar.add(this.back,this.fill);this.root.add(this.core,this.halo,this.shell,this.marker,this.shock,this.lines,this.bar);this.dummy=new THREE.Object3D();this.clear();}
 clear(){for(const m of[this.core,this.halo,this.shell,this.marker,this.shock,this.bar])m.visible=false;this.lines.count=0;}
 update(dt,time,storm){const o=storm.orb,s=storm.strike;this.clear();const segments=[],arc=(a,b,width,seed)=>{let last=a.clone();for(let i=1;i<=12;i++){const f=i/12,p=a.clone().lerp(b,f);if(i<12)p.add(new THREE.Vector3(Math.sin(i*7+time*40+seed),Math.sin(i*9+time*34),Math.cos(i*5-time*31+seed)).multiplyScalar(width>.15?.8:.18));segments.push({a:last,b:p,width});last=p;}};
  if(o){for(const m of[this.core,this.halo,this.shell]){m.visible=true;m.position.copy(o.position);}const pulse=1+Math.sin(time*9)*.04;this.core.scale.setScalar(C.orbRadius*pulse);this.halo.scale.setScalar(C.orbRadius*1.45*pulse);this.shell.scale.setScalar(C.orbRadius*1.2);this.shell.rotation.set(time*.4,time*.7,0);this.core.material.color.set(o.flash>0?'#ffffff':'#a9eaff');for(let i=0;i<4;i++){const a=time*1.5+i*Math.PI/2,p=o.position.clone().add(new THREE.Vector3(Math.cos(a),Math.sin(a*1.4),Math.sin(a)).multiplyScalar(C.orbRadius));arc(o.position,p,.025,i);}this.bar.visible=true;this.bar.position.copy(o.position).add(new THREE.Vector3(0,C.orbRadius+1,0));this.bar.quaternion.copy(this.camera.quaternion);const q=o.energy/C.orbEnergy;this.fill.scale.x=q;this.fill.position.x=-1.3*(1-q);this.fill.material.color.set(o.flash>0?'#ffffff':q<.2?'#ffb663':'#67edff');}
  if(s){this.marker.visible=true;this.marker.position.copy(s.point).y+=.08;const p=1-s.remaining/C.strikeDelay;this.marker.scale.setScalar(C.strikeRadius*(.9+.08*Math.sin(time*(5+p*18))));this.marker.material.color.set(p>.8?'#edfbff':'#60d9ff');this.marker.material.opacity=.5+p*.5;}
  for(const e of storm.events){if(e.kind==='fade'){this.shock.visible=true;this.shock.position.copy(e.point);this.shock.scale.setScalar(C.orbRadius*(1+e.age*4));this.shock.material.opacity=.18*Math.max(0,1-e.age/.25);continue;}if(e.kind==='zap'){arc(e.from,e.point,.035*(1-e.age/.25),7);continue;}if(e.kind==='strike'){const start=e.point.clone().add(new THREE.Vector3(0,65,0)),fade=1-e.age/.65;arc(start,e.point,.18*fade,5);arc(start.clone().add(new THREE.Vector3(8,0,5)),e.point,.065*fade,2);this.shock.visible=true;this.shock.position.copy(e.point).y+=.4;this.shock.scale.setScalar(Math.max(.1,C.strikeRadius*Math.min(1,e.age*7)));this.shock.material.opacity=fade*.24;}}
  let n=0;for(const p of segments){if(n>=256)break;const d=p.b.clone().sub(p.a);this.dummy.position.copy(p.a).lerp(p.b,.5);this.dummy.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.clone().normalize());this.dummy.scale.set(Math.max(.001,p.width),d.length(),Math.max(.001,p.width));this.dummy.updateMatrix();this.lines.setMatrixAt(n++,this.dummy.matrix);}this.lines.count=n;this.lines.instanceMatrix.needsUpdate=true;
 }
 diagnostics(){return{orbVisible:this.core.visible,barVisible:this.bar.visible,marker:this.marker.visible,segments:this.lines.count,limit:256};}
}
